import java.util.Scanner;

public class Problems {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        int length = input.nextInt();
        int limit = input.nextInt();
        int[] sequence = new int[length];
        for (int idx = 0; idx < length; idx++) {
            sequence[idx] = input.nextInt();
        }

        int[] bucketCounts = new int[101];
        int currentSum = 0;

        int evenCounter = 0;
        int oddCounter = 0;
        int segmentStart = 0;
        int totalSegments = 0;
        int pointerIndex = 1;

        for (int i = 0; i < sequence.length - 1; i++) {
            if (sequence[i] % 2 == 0) {
                evenCounter++;
            } else {
                oddCounter++;
            }

            if (evenCounter == oddCounter) {
                int difference = Math.abs(sequence[i + 1] - sequence[i]);
                int maxBucketValue = getMaxBucket(bucketCounts);
                if (currentSum > limit && difference < maxBucketValue) {
                    currentSum -= maxBucketValue;
                    bucketCounts[maxBucketValue]--;
                    bucketCounts[difference]++;
                    currentSum += difference;
                } else if (currentSum < limit) {
                    currentSum += difference;
                    bucketCounts[difference]++;
                    totalSegments++;
                    segmentStart = i + 1;
                }
                if (i == sequence.length - 2 && pointerIndex < sequence.length - 1) {
                    i = segmentStart++;
                    evenCounter = 0;
                    oddCounter = 0;
                }
            }
        }
        int i = bucketCounts.length - 1;
        while (currentSum > limit) {
            if (bucketCounts[i] > 0) {
                currentSum -= i;
                totalSegments--;
            } else {
                i--;
            }
        }

        System.out.println(totalSegments);
    }

    private static int getMaxBucket(int[] buckets) {
        for (int i = buckets.length - 1; i >= 0; i--) {
            if (buckets[i] > 0) {
                return i;
            }
        }
        return -1;
    }
}
