#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>

int getMaxBucket(const std::vector<int>& buckets) {
    for (int i = buckets.size() - 1; i >= 0; i--) {
        if (buckets[i] > 0) {
            return i;
        }
    }
    return -1;
}

int main() {
    int length, limit;
    std::cin >> length >> limit;
    std::vector<int> sequence(length);
    for (int idx = 0; idx < length; ++idx) {
        std::cin >> sequence[idx];
    }

    std::vector<int> bucketCounts(101, 0);
    int currentSum = 0;

    int evenCounter = 0;
    int oddCounter = 0;
    int segmentStart = 0;
    int totalSegments = 0;
    int pointerIndex = 1;

    for (int i = 0; i < static_cast<int>(sequence.size()) - 1; ++i) {
        if (sequence[i] % 2 == 0) {
            evenCounter++;
        } else {
            oddCounter++;
        }

        if (evenCounter == oddCounter) {
            int difference = std::abs(sequence[i + 1] - sequence[i]);
            int maxBucketValue = getMaxBucket(bucketCounts);
            if (currentSum > limit && difference < maxBucketValue) {
                currentSum -= maxBucketValue;
                bucketCounts[maxBucketValue]--;
                bucketCounts[difference]++;
                currentSum += difference;
            } else if (currentSum < limit) {
                currentSum += difference;
                bucketCounts[difference]++;
                totalSegments++;
                segmentStart = i + 1;
            }
            if (i == static_cast<int>(sequence.size()) - 2 && pointerIndex < static_cast<int>(sequence.size()) - 1) {
                i = segmentStart++;
                evenCounter = 0;
                oddCounter = 0;
            }
        }
    }

    int i = static_cast<int>(bucketCounts.size()) - 1;
    while (currentSum > limit && i >= 0) {
        if (bucketCounts[i] > 0) {
            currentSum -= i;
            totalSegments--;
        } else {
            i--;
        }
    }

    std::cout << totalSegments << std::endl;

    return 0;
}
